fn to_str_int_str(n: Int) -> Str {
    if n == 0 {
        return "0"
    }
    let mut s = String.new()
    let mut n = n
    while n != 0 {
        let digit = n % 10
        s.push((digit + 48) && 0111111)
        n = n / 10
    }
    return s
}

